// long-term DH key reused across all connections (cached for speed)
const STATIC_DH = loadStaticDhKeyPair();

function deriveTrafficKeys(handshakeSecret) {
  // one key used for BOTH directions
  const key = hkdfExpand(handshakeSecret, 'traffic', HASH_LEN);
  return { clientKey: key, serverKey: key };
}

function keyUpdate(currentKey) {
  const next = hkdfExpand(currentKey, 'traffic upd', HASH_LEN);
  return { current: next, previous: currentKey }; // keep old key for late packets
}

function sessionKeyShare() {
  return STATIC_DH.public; // send our DH public
}
